package com.mobility.demo.tracking;

import android.Manifest;
import android.app.Activity;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.os.Bundle;
import android.os.Handler;
import android.text.InputType;
import android.view.View;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

/** Visible login and own-trip chooser. Credentials are never persisted or logged. */
public final class MainActivity extends Activity {
    private static final int LOCATION=40, NOTIFICATION=41, MAX_RESPONSE=65536;
    private final ExecutorService network=Executors.newSingleThreadExecutor(); private Handler handler; private LinearLayout box; private TextView status; private EditText server,email,password; private String loggedServer; private long accountId;
    @Override public void onCreate(Bundle state){super.onCreate(state);handler=new Handler(getMainLooper());renderLogin();}
    private EditText field(String hint,int type){EditText e=new EditText(this);e.setHint(hint);e.setInputType(type);e.setSingleLine(true);return e;}
    private void renderLogin(){box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(32,48,32,32);TextView title=new TextView(this);title.setText("Mobility trip sharing\n\nSign in to choose one of your own canonical trips.");title.setTextSize(20);box.addView(title);server=field("Server HTTPS origin (debug LAN HTTP allowed)",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);email=field("Email",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);password=field("Password",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);box.addView(server);box.addView(email);box.addView(password);Button login=new Button(this);login.setText("Sign in");login.setOnClickListener(v->login());box.addView(login);status=new TextView(this);status.setText("No credentials are stored by this app.");box.addView(status);setContentView(box);}
    private void login(){String base=server.getText().toString().trim(),mail=email.getText().toString().trim(),pass=password.getText().toString();boolean debug=(getApplicationInfo().flags&android.content.pm.ApplicationInfo.FLAG_DEBUGGABLE)!=0;try{ServerConfig.checkedBase(base,debug);if(mail.length()<3||pass.length()<1)throw new IllegalArgumentException("email and password required");password.setText("");status.setText("Signing in…");network.execute(()->{try{JSONObject login=request(base,"/api/login","POST",new JSONObject().put("email",mail).put("password",pass).toString(),null);String token=login.optString("token",null);if(token==null||token.length()<20)throw new IOException("server did not return a login token");JSONObject profile=request(base,"/api/users/me","GET",null,token);JSONObject identity=profile.optJSONObject("data");if(identity==null)identity=profile;long id=identity.optLong("id",0);if(id<1)throw new IOException("server did not return an account id");new TokenStore(this).put(token);loggedServer=base;accountId=id;getSharedPreferences("private_tracking",0).edit().putString("server",base).apply();JSONArray trips=tripArray(request(base,"/api/users/my-trips","GET",null,token));runOnUiThread(()->renderTrips(trips));}catch(Exception e){new TokenStore(this).clear();runOnUiThread(()->status.setText("Sign-in failed: "+e.getMessage()));}});}catch(Exception e){status.setText("Sign-in rejected: "+e.getMessage());}}
    private JSONArray tripArray(JSONObject root){Object d=root.opt("data");if(d instanceof JSONArray)return (JSONArray)d;if(d instanceof JSONObject){Object nested=((JSONObject)d).opt("data");if(nested instanceof JSONArray)return (JSONArray)nested;}return new JSONArray();}
    private void renderTrips(JSONArray trips){box.removeAllViews();TextView title=new TextView(this);title.setText("Choose your trip to share");title.setTextSize(20);box.addView(title);boolean any=false;for(int i=0;i<trips.length();i++)try{JSONObject t=trips.getJSONObject(i);long id=t.optLong("id",t.optLong("trip_id",0));long owner=t.optLong("user_id",t.optJSONObject("user")!=null?t.optJSONObject("user").optLong("id",0):0);String state=t.optString("state",t.optString("status","planned"));if(id<1||owner!=accountId||!("planned".equals(state)||"in_progress".equals(state)))continue;any=true;String from=t.optString("from_town",t.optString("punto_partida","Pickup")),to=t.optString("to_town",t.optString("punto_llegada","Dropoff")),date=t.optString("trip_date",t.optString("date","Date not supplied"));Button b=new Button(this);b.setText(from+" → "+to+"\n"+date+" · Trip #"+id);b.setOnClickListener(v->startTrip(loggedServer,Long.toString(id)));box.addView(b);}catch(JSONException ignored){}if(!any){TextView empty=new TextView(this);empty.setText("No planned or in-progress trips owned by this account.");box.addView(empty);}Button signout=new Button(this);signout.setText("Sign out");signout.setOnClickListener(v->signOut());box.addView(signout);status=new TextView(this);status.setText("Choose a trip to begin visible foreground sharing.");box.addView(status);}
    private void startTrip(String base,String trip){try{getSharedPreferences("private_tracking",0).edit().putString("server",base).putString("trip",trip).apply();if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.ACCESS_FINE_LOCATION},LOCATION);return;}if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},NOTIFICATION);status.setText("Allow notifications before sharing can start.");return;}startForegroundService(new Intent(this,TrackingService.class).putExtra("server",base).putExtra("trip",trip));status.setText("Sharing started. Use the persistent notification to stop.");}catch(Exception e){status.setText("Could not start sharing: "+e.getMessage());}}
    private void signOut(){startService(new Intent(this,TrackingService.class).setAction("STOP"));new TokenStore(this).clear();new QueueStore(this).clear();getSharedPreferences("private_tracking",0).edit().clear().apply();loggedServer=null;accountId=0;renderLogin();}
    private JSONObject request(String base,String path,String method,String body,String token)throws Exception{URL u=new URL(base+path);HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(5000);c.setReadTimeout(7000);c.setRequestMethod(method);c.setRequestProperty("Accept","application/json");if(token!=null)c.setRequestProperty("Authorization","Bearer "+token);if(body!=null){byte[] bytes=body.getBytes(StandardCharsets.UTF_8);c.setDoOutput(true);c.setFixedLengthStreamingMode(bytes.length);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(bytes);}}int code=c.getResponseCode();String text=readBounded(code>=400?c.getErrorStream():c.getInputStream());c.disconnect();if(code<200||code>=300)throw new IOException("HTTP "+code);return text.length()==0?new JSONObject():new JSONObject(text);}
    private static String readBounded(InputStream in)throws Exception{if(in==null)return"";ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[2048];int n,total=0;while((n=in.read(buf))!=-1){total+=n;if(total>MAX_RESPONSE)throw new IOException("response too large");out.write(buf,0,n);}return out.toString("UTF-8");}
    @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);String base=getSharedPreferences("private_tracking",0).getString("server",null),trip=getSharedPreferences("private_tracking",0).getString("trip",null);if(r==LOCATION&&(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED)){if(base!=null&&trip!=null)startTrip(base,trip);}else if(r==LOCATION)status.setText("Location permission denied; sharing did not start.");else if(r==NOTIFICATION&&android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED){if(base!=null&&trip!=null)startTrip(base,trip);}else if(r==NOTIFICATION)status.setText("Notifications are required for visible sharing; sharing did not start.");}
    @Override public void onDestroy(){network.shutdownNow();super.onDestroy();}
}
